/**
 * The SEO pages generated by `node seo/scripts/build.mjs` into seo/public/ (English only; the old
 * translated pages /es/ /pt/ /fr/ /de/ /it/ /ro/ /pl/ /tr/ redirect to the home page): new English categories,
 * quiz of the day, Q&A list, flags by continent, the embeddable widget (/embed/), /flags/*.svg,
 * sitemap-i18n.xml and llms.txt.
 *
 * Also reads sitemap-i18n.xml so the server-rendered English pages can declare the same hreflang
 * clusters in their <head> (the sitemap and the pages must agree).
 */
import express from 'express';
import fs from 'node:fs';
import path from 'node:path';
import { SERVER_ROOT } from './paths';
import { contentSecurityPolicy, scriptHash } from './security';
import { publicUrl } from './seo';

export const PACK_PUBLIC = process.env.SEO_PACK_DIR ?? path.resolve(SERVER_ROOT, '..', 'seo', 'public');
const SITEMAP_ORIGIN = 'https://1v1game.net'; // the pack is built for the canonical origin

type Alt = { lang: string; href: string };
let alternates: Map<string, Alt[]> | null = null;

/** path (e.g. "/quiz/geography") → its hreflang cluster, from sitemap-i18n.xml. */
function loadAlternates(): Map<string, Alt[]> {
  if (alternates) return alternates;
  alternates = new Map();
  const file = path.join(PACK_PUBLIC, 'sitemap-i18n.xml');
  if (!fs.existsSync(file)) return alternates;
  const xml = fs.readFileSync(file, 'utf8');
  for (const m of xml.matchAll(/<url>([\s\S]*?)<\/url>/g)) {
    const loc = /<loc>([^<]+)<\/loc>/.exec(m[1])?.[1];
    if (!loc) continue;
    const alts = [...m[1].matchAll(/hreflang="([^"]+)" href="([^"]+)"/g)].map((a) => ({ lang: a[1], href: a[2] }));
    alternates.set(loc.replace(SITEMAP_ORIGIN, ''), alts);
  }
  return alternates;
}

/** <link rel="alternate" hreflang> tags for an English page: its translations if it has any, else itself. */
export function hreflangTags(pagePath: string): string {
  const base = publicUrl();
  const alts = loadAlternates().get(pagePath) ?? [{ lang: 'en', href: SITEMAP_ORIGIN + pagePath }, { lang: 'x-default', href: SITEMAP_ORIGIN + pagePath }];
  return alts.map((a) => `<link rel="alternate" hreflang="${a.lang}" href="${a.href.replace(SITEMAP_ORIGIN, base)}">`).join('');
}

export const hasPack = () => fs.existsSync(path.join(PACK_PUBLIC, 'sitemap-i18n.xml'));

/** sha256 CSP sources of the inline (executable) scripts of one generated page, cached per file. */
const hashCache = new Map<string, string[]>();
function inlineScriptHashes(file: string): string[] {
  let h = hashCache.get(file);
  if (!h) {
    const html = fs.readFileSync(file, 'utf8');
    h = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map((m) => scriptHash(m[1]));
    hashCache.set(file, h);
  }
  return h;
}

export function mountSeoPack(app: express.Express) {
  // The translated pages (/es/, /pt/, /fr/, /de/, /it/, /ro/, /pl/, /tr/ and everything under them)
  // were removed: the site is English only. Old links and search results go to the home page.
  app.use((req, res, next) => {
    if (/^\/(es|pt|fr|de|it|ro|pl|tr)(\/|$)/.test(req.path)) return res.redirect(301, '/');
    next();
  });

  if (!hasPack()) {
    console.warn(`[duel] SEO pack not built (${PACK_PUBLIC}); run: node seo/scripts/build.mjs`);
    return;
  }
  const embedDir = path.join(PACK_PUBLIC, 'embed') + path.sep;

  // "/es" → "/es/" (the generated pages are directories; their canonicals end with a slash).
  // Only when that directory has an index.html, so "/quiz" and "/flag-quiz" stay with the game server.
  app.use((req, res, next) => {
    if ((req.method !== 'GET' && req.method !== 'HEAD') || req.path.endsWith('/') || path.extname(req.path)) return next();
    const rel = path.normalize(decodeURIComponent(req.path)).replace(/^([/\\])+/, '');
    const index = path.join(PACK_PUBLIC, rel, 'index.html');
    if (!index.startsWith(PACK_PUBLIC) || !fs.existsSync(index)) return next();
    const q = req.originalUrl.slice(req.path.length);
    res.redirect(301, `${req.path}/${q}`);
  });

  app.use(
    express.static(PACK_PUBLIC, {
      index: 'index.html',
      redirect: false,
      setHeaders(res, file) {
        if (file.endsWith('.html')) {
          const framable = file.startsWith(embedDir);
          // The widget page lives inside other sites' iframes; everything else keeps frame-ancestors 'none'.
          if (framable) res.removeHeader('X-Frame-Options');
          res.setHeader('Content-Security-Policy', contentSecurityPolicy(inlineScriptHashes(file), { framable }));
          res.setHeader('Cache-Control', 'public, max-age=600, stale-while-revalidate=86400');
        } else if (file.endsWith('.svg')) res.setHeader('Cache-Control', 'public, max-age=604800');
        else res.setHeader('Cache-Control', 'public, max-age=3600');
      },
    }),
  );
}
